from solution import get_max_triples
import pytest
from hypothesis import given
import hypothesis.strategies as st


def brute(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    c = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    c += 1
    return c


def residue_model(n):
    c0 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 0)
    c1 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 1)
    c2 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 2)
    assert c2 == 0
    def C3(m):
        return m * (m - 1) * (m - 2) // 6 if m >= 3 else 0
    return C3(c0) + C3(c1)


def test_spec_example_n5():
    assert get_max_triples(5) == 1


def test_n1_no_triple():
    assert get_max_triples(1) == 0


def test_n2_no_triple():
    assert get_max_triples(2) == 0


def test_n3_no_triple():
    # a = [1, 3, 7], sum = 11 not multiple of 3
    assert get_max_triples(3) == 0


def test_n4_one_triple():
    # a = [1,3,7,13], only (1,7,13) sums to 21
    assert get_max_triples(4) == 1


def test_result_type_is_int():
    for n in [1, 2, 3, 4, 5, 10]:
        r = get_max_triples(n)
        assert type(r) is int


def test_result_nonnegative_and_bounded():
    for n in [1, 2, 3, 4, 5, 10, 20]:
        r = get_max_triples(n)
        assert r >= 0
        assert r <= n * (n - 1) * (n - 2) // 6 if n >= 3 else r == 0


@given(st.integers(min_value=1, max_value=30))
def test_equivalence_to_brute(n):
    assert get_max_triples(n) == brute(n)


@given(st.integers(min_value=1, max_value=200))
def test_equivalence_to_residue_model(n):
    assert get_max_triples(n) == residue_model(n)


@given(st.integers(min_value=1, max_value=100))
def test_monotone_non_decreasing(n):
    assert get_max_triples(n + 1) >= get_max_triples(n)


@given(st.integers(min_value=1, max_value=100))
def test_increment_bounded_by_pairs(n):
    # new triples using index n+1 as largest are at most C(n,2)
    diff = get_max_triples(n + 1) - get_max_triples(n)
    assert 0 <= diff <= n * (n - 1) // 2
